import os
import hmac
import hashlib
import time
from flask import Flask, request, jsonify, abort
from lxml import etree

app = Flask(__name__)

SECRET_KEY = os.environ.get('WEBHOOK_SECRET', 'default-dev-key')
UPLOAD_DIR = os.environ.get('UPLOAD_DIR', '/tmp/uploads')

def verify_signature(payload, signature):
    """Verify HMAC-SHA256 signature from webhook provider."""
    if not signature:
        return False
    expected = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(f'sha256={expected}', signature)

def parse_config_payload(xml_data):
    """Parse incoming XML configuration from CI/CD webhook.
    Supports nested config elements with variable expansion."""
    parser = etree.XMLParser(
        resolve_entities=True,
        no_network=False,
        dtd_validation=False,
        load_dtd=True
    )
    try:
        root = etree.fromstring(xml_data, parser=parser)
    except etree.XMLSyntaxError as e:
        return None, str(e)

    config = {}
    for elem in root.iter():
        if elem.text and elem.text.strip():
            config[elem.tag] = elem.text.strip()

    return config, None

def validate_config_schema(config):
    """Basic schema validation for deployment config."""
    required_fields = ['service_name', 'version', 'environment']
    for field in required_fields:
        if field not in config:
            return False, f'Missing required field: {field}'

    if not config.get('version', '').replace('.', '').isdigit():
        return False, 'Invalid version format'

    allowed_envs = ['staging', 'production', 'canary']
    if config.get('environment') not in allowed_envs:
        return False, f'Invalid environment: must be one of {allowed_envs}'

    return True, None

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

@app.route('/api/v1/deployments/webhook', methods=['POST'])
def deployment_webhook():
    """Receive deployment configuration from CI/CD pipeline.
    Expects XML payload with HMAC signature in X-Hub-Signature-256 header."""

    content_type = request.headers.get('Content-Type', '')
    if 'xml' not in content_type.lower():
        abort(415, description='Content-Type must be application/xml')

    raw_body = request.get_data()
    if len(raw_body) > 65536:
        abort(413, description='Payload too large')

    # Signature verification
    sig_header = request.headers.get('X-Hub-Signature-256')
    if not verify_signature(raw_body, sig_header):
        abort(401, description='Invalid signature')

    # Parse XML config
    config, parse_error = parse_config_payload(raw_body)
    if parse_error:
        return jsonify({'error': 'XML parse error', 'detail': parse_error}), 400

    # Validate schema
    valid, validation_error = validate_config_schema(config)
    if not valid:
        return jsonify({'error': 'Validation failed', 'detail': validation_error}), 422

    # Store config for deployment controller
    config_path = os.path.join(UPLOAD_DIR, f"{config['service_name']}_{config['version']}.json")
    import json
    with open(config_path, 'w') as f:
        json.dump(config, f)

    return jsonify({
        'status': 'accepted',
        'service': config['service_name'],
        'version': config['version'],
        'environment': config['environment']
    }), 202

@app.route('/api/v1/deployments', methods=['GET'])
def list_deployments():
    """List stored deployment configs."""
    try:
        files = os.listdir(UPLOAD_DIR)
        return jsonify({'deployments': [f.replace('.json', '') for f in files if f.endswith('.json')]})
    except FileNotFoundError:
        return jsonify({'deployments': []})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080, debug=False)
